/* Engineering episode: an original teaching model, grounded in the supplied career materials. */
(() => {
 'use strict';
 const key='ochakovo-engineering-story-v1';
 const steps=[
 ['welcome','factory','Другой формат. Та же точность','Сегодня линия переходит на более широкую банку. Разберёмся, что нужно изменить, чтобы оборудование работало согласованно.','Начни смену вместе со мной.'],
 ['tour','factory','Познакомься с узлом','Направляющие удерживают тару на пути. Датчик замечает её появление, а привод двигает ленту. Нажми на три детали и узнай их роль.','Исследуй три отмеченных узла.'],
 ['order','bench','Сначала — задание','Банка стала шире. Важно сопоставить новый формат с оснасткой и программой: одна механическая регулировка не решает всю задачу.','Выбери тару из нового задания: формат Б.'],
 ['baseline','factory','Проверь свою гипотезу','На виртуальной модели посмотрим, что произойдёт с новой банкой при прежней настройке. На настоящем участке такие проверки выполняют по утверждённому порядку.','Запусти модель и проследи за банкой.'],
 ['locate','factory','Что мешает проходу?','Банка упирается на входе. Лента движется, датчик видит тару. Найди деталь, геометрия которой не подходит новому формату.','Выбери узел прямо на модели.'],
 ['prepare','factory','Подготовка к переналадке','На работающую линию не вмешиваются. Подготовку оборудования и допуск организует наставник. Для следующего шага он передаст тебе безопасный учебный макет.','Попроси наставника подготовить макет.'],
 ['tooling','bench','Подбери оснастку','У двух комплектов разная ширина прохода. Сопоставь их с широкой банкой и маркировкой задания. Наладчик подбирает оснастку под конкретный формат.','Выбери комплект Б.'],
 ['install','bench','Деталь должна встать на место','Оснастка выбрана. На учебном макете совмести направляющие с посадочными местами. За крепление и проверку готовности отвечает наставник.','Установи выбранный комплект на макет.'],
 ['gap','bench','Оставь место для прохода','Слишком узко — банка застрянет. Слишком широко — потеряет направление. Выставь зазор по карточке учебного задания.','Учебная шкала: рабочая отметка — 4.'],
 ['chain','control','Как оборудование понимает команду','Автоматика связывает наблюдение и движение. Датчик обнаруживает банку, контроллер обрабатывает сигнал, привод выполняет команду.','Собери путь сигнала, нажимая на устройства по порядку.'],
 ['recipe','control','Механика и программа — одна задача','Направляющие уже рассчитаны на формат Б. Теперь выбери для него задание на учебном терминале. Настройка должна соответствовать установленной оснастке.','Выбери формат Б и примени задание.'],
 ['dry','factory','Сначала — без продукции','Наставник проверил сборку и готовность. Посмотри пробный цикл без банок: лента должна двигаться, а узел — завершить цикл без остановки.','Проведи проверку пустого узла.'],
 ['test','factory','Теперь — пробный проход','Пустой цикл прошёл. Проверим три учебные банки: каждая должна пройти между направляющими, а датчик — отметить каждую.','Запусти пробный проход и наблюдай за счётчиком.'],
 ['inspect','factory','Число — ещё не весь результат','Три сигнала получены. Но инженер также проверяет, как прошла тара: без застревания, перекоса и повреждения. Осмотри каждую банку на выходе.','Нажми на три банки, чтобы проверить результат.'],
 ['record','control','Передай понятный результат','Команде нужно знать, что изменили и чем подтвердили результат. Запиши формат, настройку и проверку. «Всё хорошо» не поможет следующей смене.','Выбери запись, по которой можно восстановить ход работы.'],
 ['finish','factory','Ты связал механику и автоматику','Ты сопоставил тару и оснастку, настроил учебный узел, разобрал путь сигнала и подтвердил результат проверкой. Так из отдельных действий складывается инженерная задача.','В материалах «Очаково» есть работа с инженером, оцифровка линии и поиск улучшений.']
 ];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const btn=(a,t,cls='')=>`<button type="button" class="es-button ${cls}" data-es="${a}">${t}</button>`;
 const can=(x,y,wide=true,n='',extra='')=>`<g transform="translate(${x} ${y})" ${extra}><ellipse cx="0" cy="91" rx="39" ry="10" fill="#243d4520"/><path d="M${wide?-30:-23} 0 Q0 -10 ${wide?30:23} 0 L${wide?33:26} 78 Q0 94 ${wide?-33:-26} 78Z" fill="${wide?'#bd493b':'#467f86'}" stroke="#344e56" stroke-width="3"/><path d="M${wide?-28:-21} 20 Q0 30 ${wide?28:21} 20V60Q0 72 ${wide?-28:-21} 60Z" fill="#fff3cf"/><path d="M-24 11Q0 19 24 11M-25 73Q0 82 25 73" fill="none" stroke="#e2e2c9" stroke-width="2"/><path d="M-16 28v25" stroke="#fff" stroke-width="5" opacity=".6"/><ellipse cx="0" cy="0" rx="${wide?30:23}" ry="9" fill="#ced8d2" stroke="#344e56" stroke-width="3"/><ellipse cx="3" cy="0" rx="9" ry="4" fill="#849a99"/><text x="0" y="51" text-anchor="middle" fill="#344e56" font-size="23" font-weight="800">${n|| (wide?'Б':'А')}</text></g>`;
 const target=(action,label,svg,selected=false)=>`<g class="es-target ${selected?'is-selected':''}" data-es="${action}" role="button" tabindex="0" aria-label="${label}"><title>${label}</title>${svg}</g>`;
 const svg=(body,cls='')=>`<svg class="es-art ${cls}" viewBox="0 0 1000 540" xmlns="http://www.w3.org/2000/svg" aria-label="Учебная модель оборудования"><defs><linearGradient id="es-metal" x2="0.2" y2="1"><stop stop-color="#f8f0d9"/><stop offset=".43" stop-color="#c7d5cc"/><stop offset="1" stop-color="#8eaaa8"/></linearGradient><linearGradient id="es-body" x2="0.3" y2="1"><stop stop-color="#86aba8"/><stop offset="1" stop-color="#426f78"/></linearGradient><linearGradient id="es-belt-tone" x2="0" y2="1"><stop stop-color="#647d7a"/><stop offset="1" stop-color="#97aaa2"/></linearGradient></defs>${body}</svg>`;
 function machine(s){
  const tour=s.step===1,locate=s.step===4,inspect=s.step===13,passed=s.step>=12,wide=s.step>=8;
  const interact=(a,label,body)=>tour||locate?target(a,label,body,s.checked.includes(a)):`<g>${body}</g>`;
  return svg(`<ellipse cx="510" cy="475" rx="425" ry="40" fill="#243d4528"/>
   <path d="M150 310v145h40V325M770 310v145h40V325" fill="#527d7e" stroke="#344e56" stroke-width="5"/>
   <path d="M100 265L804 225 925 332 207 389Z" fill="url(#es-metal)" stroke="#344e56" stroke-width="4"/>
   <path d="M100 265v57l107 114v-47M207 389l718-57v51l-718 53Z" fill="url(#es-body)" stroke="#344e56" stroke-width="4"/>
   <path d="M125 268L800 244 895 326 213 368Z" fill="url(#es-belt-tone)" stroke="#344e56" stroke-width="3"/>
   <g class="es-belt">${Array.from({length:17},(_,i)=>`<path d="M${140+i*39} ${268-i*1.3}l80 86" stroke="#b8c7bd" stroke-width="4"/>`).join('')}</g>
   ${interact('motor','Привод',`<g class="es-motor"><path d="M725 365q-35-20-62 3t-46-2" fill="none" stroke="#344e56" stroke-width="6"/><path d="M726 361l67-7 19 34-65 10Z" fill="#3d5964" stroke="#263e48" stroke-width="4"/><ellipse cx="769" cy="394" rx="41" ry="34" fill="url(#es-metal)" stroke="#344e56" stroke-width="4"/><circle cx="769" cy="394" r="24" fill="#537c80"/><g class="es-wheel"><circle cx="769" cy="394" r="20" fill="#354f5a"/>${Array.from({length:6},(_,i)=>`<path d="M769 388q-17-14-18 0l12 9Z" fill="#a8beb4" transform="rotate(${i*60} 769 394)"/>`).join('')}<circle cx="769" cy="394" r="6" fill="#e5ead4" stroke="#344e56" stroke-width="2"/></g></g>${tour||locate?'<g class="es-badge"><circle cx="818" cy="418" r="22" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="818" y="425" text-anchor="middle" font-size="21" fill="#b94337">3</text></g>':''}`)}
   ${interact('guides','Направляющие',`<g class="es-guides"><rect x="420" y="205" width="335" height="145" fill="#fff" opacity="0"/><path d="M430 ${wide?227:248}L715 ${wide?216:237}v14L430 ${wide?241:262}Z" fill="url(#es-metal)" stroke="#344e56" stroke-width="4"/><path d="M440 ${wide?329:302}L725 ${wide?316:289}v15L440 ${wide?344:317}Z" fill="#d4cbb4" stroke="#344e56" stroke-width="4"/><path d="M470 255v-17m210 7v-18M480 312v45m210-55v40" stroke="#344e56" stroke-width="7"/></g>${tour||locate?'<g class="es-badge"><circle cx="550" cy="194" r="22" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="550" y="201" text-anchor="middle" font-size="21" fill="#b94337">1</text></g>':''}`)}
   ${interact('sensor','Датчик',`<path d="M605 249V146h36v101" fill="#8aaba6" stroke="#344e56" stroke-width="4"/><rect x="591" y="142" width="65" height="38" rx="7" fill="#344e56"/><path d="M597 149h52" stroke="#839e98" stroke-width="3"/><circle cx="598" cy="173" r="2" fill="#d0d8c5"/><circle cx="649" cy="173" r="2" fill="#d0d8c5"/><circle class="es-sensor-light" cx="620" cy="162" r="10" fill="${passed?'#a4cb93':'#eac871'}"/>${tour||locate?'<g class="es-badge"><circle cx="679" cy="153" r="22" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="679" y="160" text-anchor="middle" font-size="21" fill="#b94337">2</text></g>':''}`)}
   <g class="es-cans">${s.step===3?can(250,211,true,'','class="es-moving-can"'):s.step===4?can(385,202):s.step===12?'':s.step===13? [640,740,840].map((x,i)=>target('can'+i,'Осмотреть банку '+(i+1),can(x,210,true,s.checked.includes('can'+i)?'✓':String(i+1)),s.checked.includes('can'+i))).join(''):s.step===0||s.step===1?can(260,211,false)+can(380,206,false):''}</g>
   <path d="M226 402l490-36m110-9 82-6" stroke="#c7dad0" stroke-width="2" opacity=".7"/>${[250,500,870].map(x=>`<circle cx="${x}" cy="${424-(x-250)*.073}" r="4" fill="#c9d5ca" stroke="#3e5e65" stroke-width="2"/><path d="M${x-2} ${424-(x-250)*.073}h4" stroke="#3e5e65"/>`).join('')}<path d="M145 444h52v14h-52M764 444h52v14h-52" fill="#344e56"/><path d="M340 395l140-12v35l-140 11Z" fill="#f5edda"/><text x="410" y="414" text-anchor="middle" fill="#344e56" font-size="17" font-weight="800" transform="rotate(-4 410 414)">УЧЕБНЫЙ УЗЕЛ</text>
   ${s.step===12?'<g transform="translate(785 125)"><rect width="116" height="64" rx="8" fill="#344e56"/><text class="es-counter" x="58" y="42" text-anchor="middle" font-size="30" fill="#f7efd9">0 / 3</text></g>':''}`);
 }
 function bench(s){
  if(s.step===2)return svg(`<ellipse cx="500" cy="436" rx="310" ry="35" fill="#344e561c"/>${target('formatA','Формат А — прежняя узкая банка',`<g transform="translate(325 220) scale(1.75)">${can(0,0,false)}</g>`)}${target('formatB','Формат Б — новая широкая банка',`<g transform="translate(665 220) scale(1.75)">${can(0,0,true)}</g>`)}<text x="325" y="443" text-anchor="middle" fill="#344e56" font-size="22" font-weight="800">Формат А</text><text x="665" y="443" text-anchor="middle" fill="#344e56" font-size="22" font-weight="800">Формат Б</text>`);
  const kit=(x,wide,label)=>`<g transform="translate(${x} 265)"><path d="M-125-25h250v120h-250Z" fill="#d6cdb5" stroke="#344e56" stroke-width="3"/><path d="M-105-5h210v15h-210ZM-105 ${wide?65:35}h210v15h-210Z" fill="#eff0dc" stroke="#344e56" stroke-width="4"/><circle cx="-85" cy="3" r="4" fill="#547376"/><circle cx="85" cy="3" r="4" fill="#547376"/><text x="0" y="125" text-anchor="middle" fill="#344e56" font-size="24" font-weight="800">Комплект ${label}</text></g>`;
  if(s.step===6)return svg(`${can(500,160,true)}${target('kitA','Комплект А — узкий',kit(250,false,'А'))}${target('kitB','Комплект Б — широкий',kit(750,true,'Б'))}`);
  return svg(`<ellipse cx="500" cy="444" rx="320" ry="33" fill="#344e5620"/><path d="M180 242h640l-50 190H230Z" fill="url(#es-metal)" stroke="#344e56" stroke-width="4"/><path d="M230 432h540v27H230Z" fill="#5e8988" stroke="#344e56" stroke-width="4"/><path d="M300 280h400M300 380h400" stroke="#557d7d" stroke-width="4" stroke-dasharray="8 10"/><g class="es-assembly" ${s.step===7?'transform="translate(0 -95)"':''}><path d="M295 278h410v15H295Z" fill="#f4ecd7" stroke="#344e56" stroke-width="4"/><path class="es-front-guide" d="M295 ${s.step===8?310+s.gap*12:374}h410v15H295Z" fill="#e3dbc2" stroke="#344e56" stroke-width="4"/><circle cx="315" cy="285" r="5" fill="#637c7d"/><circle cx="685" cy="285" r="5" fill="#637c7d"/></g>${can(500,264,true)}`);
 }
 function terminal(s){
  if(s.step===9){const labels=[['drive','Привод','Двигает'],['sensor','Датчик','Обнаруживает'],['controller','Контроллер','Принимает решение']];return `<div class="es-chain"><div class="es-signal-path">${[0,1,2].map((_,i)=>`<span class="${s.chain[i]?'is-filled':''}">${s.chain[i]?({sensor:'Датчик',controller:'Контроллер',drive:'Привод'})[s.chain[i]]:i+1}</span>`).join('<b>→</b>')}</div><div class="es-components">${labels.map(([id,name,verb],i)=>`<button class="es-component" data-es="${id}" ${s.chain.includes(id)?'disabled':''}><svg viewBox="0 0 160 120" aria-hidden="true">${i===0?'<rect x="25" y="35" width="110" height="65" rx="12" fill="#638d8c" stroke="#344e56" stroke-width="3"/><path d="M35 45h90M35 53h90M35 61h90M35 69h90M35 77h90" stroke="#94b5ac" stroke-width="3"/><circle cx="80" cy="65" r="32" fill="#d9dfcc"/><circle cx="80" cy="65" r="22" fill="#47666c"/><path d="M65 52l30 26m-30 0 30-26M80 43v44" stroke="#b4c9bc" stroke-width="4"/><circle cx="80" cy="65" r="6" fill="#e1e7ce"/>':i===1?'<path d="M65 95V30h35v65" fill="#9eb7ad"/><rect x="40" y="20" width="80" height="50" rx="7" fill="#344e56"/><circle cx="80" cy="45" r="14" fill="#ecc16a"/>':'<rect x="20" y="15" width="120" height="90" rx="8" fill="#d7deca" stroke="#344e56" stroke-width="4"/><rect x="40" y="32" width="80" height="35" fill="#4e7d7d"/><path d="M44 41h30m-30 10h45m-45 9h25" stroke="#c3d6a9" stroke-width="3"/><path d="M38 82h84M38 94h84" stroke="#91a79e" stroke-width="3"/><circle cx="113" cy="80" r="5" fill="#b7483b"/>'}</svg><strong>${name}</strong><small>${verb}</small></button>`).join('')}</div></div>`;}
  const body=s.step===10?`<p class="es-screen-label">ЗАДАНИЕ НА ПЕРЕНАЛАДКУ</p><h2>Формат тары</h2><div class="es-recipes">${btn('recipeA','А <small>Узкая банка</small>','es-recipe')}${btn('recipeB','Б <small>Широкая банка</small>','es-recipe')}</div><p>Установлено: комплект Б · зазор 4</p>`:s.step===14?`<p class="es-screen-label">ЖУРНАЛ ПЕРЕНАЛАДКИ · СМЕНА 01</p><h2>Что передадим команде?</h2>${btn('recordBad','Линия готова, всё хорошо.','es-record-option')}${btn('recordGood','Формат Б · комплект Б · зазор 4.<br>Пустой цикл пройден. Три банки прошли без замечаний.','es-record-option')}`:'';
  return `<div class="es-terminal"><div class="es-display">${body}</div><div class="es-terminal-foot"><span></span>УЧЕБНЫЙ ТЕРМИНАЛ</div></div>`;
 }
 function mount(host,{onComplete=()=>{}}={}){
  const fresh=()=>({step:0,checked:[],chain:[],gap:2});
  let s=fresh(),busy=false,disposed=false,paused=false,storageOK=true,animations=[],ready=false,tip=null,lastAction='',lastTrigger=null,signalFrame=0;
  try {const v=JSON.parse(localStorage.getItem(key));if(v&&Number.isInteger(v.step)&&v.step>=0&&v.step<steps.length){s={step:v.step,checked:[...new Set((v.checked||[]).filter(x=>['guides','sensor','motor','can0','can1','can2'].includes(x)))],chain:['sensor','controller','drive'].slice(0,Array.isArray(v.chain)?v.chain.findIndex((x,i)=>x!==['sensor','controller','drive'][i])===-1?Math.min(v.chain.length,3):0:0),gap:[1,2,3,4,5,6].includes(v.gap)?v.gap:2};}}catch{}
  const q=x=>host.querySelector(x), all=x=>[...host.querySelectorAll(x)];
  const save=()=>{try{localStorage.setItem(key,JSON.stringify(s));}catch{storageOK=false;}};
  save();
  const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||window.GameMotion?.enabled()===false;
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">${({back:'<path d="M18 12H5m6-7-7 7 7 7"/>',book:'<path d="M4 4h16v16H4zM12 4v16"/>',help:'<path d="M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 3v2"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 5 11 7-11 7Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>'})[name]}</svg>`;
  function tween(el,frames,duration=300,delay=0){if(!el)return null;const a=el.animate(frames,{duration:reduced()?1:duration,delay:reduced()?0:delay,fill:'forwards',easing:'cubic-bezier(.22,.68,.28,1)'});animations.push(a);return a;}
  function cleanupMotion(){cancelAnimationFrame(signalFrame);animations.forEach(a=>a.cancel());animations=[];busy=false;}
  function mark(a){const el=q(`[data-es="${a}"]`);if(!el)return;el.classList.add('is-selected');el.setAttribute('aria-pressed','true');const badge=el.querySelector('.es-badge text');if(badge)badge.textContent='✓';tween(el,[{filter:'drop-shadow(0 0 0px #d7b461)'},{filter:'drop-shadow(0 0 9px #f3d481)'},{filter:'drop-shadow(0 2px 1px #425e5b44)'}],400);}
  function positionTip(){const box=q('.es-object-popover'),world=q('.es-world');if(!box||!tip||!world)return;const target=q(`[data-es="${tip.anchor}"]`)||q(tip.anchor)||q('.es-art,.es-terminal,.es-chain');if(!target)return;
   const w=world.getBoundingClientRect(),r=target.getBoundingClientRect(),b=box.getBoundingClientRect(),pad=16;
   const heading=q('.es-scene-heading')?.getBoundingClientRect();const top=heading?heading.bottom-w.top+12:22;
   const cx=r.left-w.left+r.width/2,cy=r.top-w.top+r.height/2;
   const avoid=all('.es-target,.es-component,.es-actions').map(n=>n.getBoundingClientRect());
   const candidates=[[cx-b.width/2,r.top-w.top-b.height-20],[r.left-w.left-b.width-24,cy-b.height/2],[r.right-w.left+24,cy-b.height/2],[cx-b.width/2,r.bottom-w.top+18]];
   const ranked=candidates.map(([px,py])=>{const x=Math.max(pad,Math.min(w.width-b.width-pad,px)),y=Math.max(top,Math.min(w.height-b.height-84,py));let score=Math.abs(x-px)+Math.abs(y-py);for(const a of avoid){const ix=Math.max(0,Math.min(x+b.width,a.right-w.left+8)-Math.max(x,a.left-w.left-8));const iy=Math.max(0,Math.min(y+b.height,a.bottom-w.top+8)-Math.max(y,a.top-w.top-8));score+=ix*iy*4;}return {x,y,score};}).sort((a,b)=>a.score-b.score);
   const {x,y}=ranked[0];
   box.style.left=x+'px';box.style.top=y+'px';
   const ax=Math.max(10,Math.min(w.width-10,r.left-w.left+r.width/2)),ay=r.top-w.top+Math.min(r.height/2,28);
   const bx=Math.max(x+12,Math.min(x+b.width-12,ax)),by=ay<y?y:y+b.height;
   const line=q('.es-tip-line');line.setAttribute('viewBox',`0 0 ${w.width} ${w.height}`);line.innerHTML=`<path d="M${bx} ${by}L${ax} ${ay}"/><circle cx="${ax}" cy="${ay}" r="4"/>`;
  }
  function showTip(title,text,anchor=lastAction,tone='info'){
   tip={title,text,anchor,tone};q('.es-object-popover')?.remove();q('.es-tip-line')?.remove();
   q('.es-world').insertAdjacentHTML('beforeend',`<svg class="es-tip-line" aria-hidden="true"></svg><aside class="es-object-popover" data-tone="${tone}" role="status"><span>${tone==='success'?'✓ ПОДТВЕРЖДЕНО':tone==='retry'?'ПОСМОТРИ ВНИМАТЕЛЬНЕЕ':'РАЗБЕРЁМСЯ В ДЕТАЛЯХ'}</span><strong>${esc(title)}</strong><p>${esc(text)}</p></aside>`);
   positionTip();tween(q('.es-object-popover'),[{opacity:0,translate:'0 8px',scale:'.97'},{opacity:1,translate:'0 0',scale:'1'}],230);
   q('.es-live').textContent=title+'. '+text;
  }
  function advance(){if(disposed)return;cleanupMotion();s.step=Math.min(15,s.step+1);s.checked=[];ready=false;tip=null;save();render(true);}
  const miniProgress=()=>`<span class="es-count">${[0,1,2].map((_,i)=>`<i class="${i<s.checked.length?'done':''}">${i<s.checked.length?'✓':i+1}</i>`).join('')} ${s.step===13?'Проверено':'Изучено'} ${s.checked.length} / 3</span>`;
  function controls(){if(ready)return btn('next',({2:'Принять задание',4:'К переналадке',6:'Взять комплект Б',8:'Перейти к автоматике',10:'Проверить узел',14:'Завершить смену'})[s.step]||'Продолжить '+icon('arrow'),'es-primary');
   switch(s.step){case 0:return btn('next','Начать смену '+icon('arrow'),'es-primary');case 1:case 13:return s.checked.length===3?btn('next',s.step===1?'Получить задание '+icon('arrow'):'Записать результат '+icon('arrow'),'es-primary'):miniProgress();case 3:return btn('baseline','Запустить модель '+icon('arrow'),'es-primary');case 5:return btn('prepare','Подготовить макет с наставником '+icon('arrow'),'es-primary');case 7:return btn('install','Установить направляющие '+icon('arrow'),'es-primary');case 8:return `<label class="es-slider">Зазор <output>${s.gap}</output><input type="range" min="1" max="6" step="1" value="${s.gap}" aria-label="Зазор направляющих"></label>${btn('gap','Проверить настройку '+icon('arrow'),'es-primary')}`;case 9:return s.chain.length===3?btn('next','К заданию на терминале '+icon('arrow'),'es-primary'):btn('chainReset','Собрать заново','es-subtle');case 11:return btn('dry','Проверить без продукции '+icon('arrow'),'es-primary');case 12:return btn('test','Запустить три банки '+icon('arrow'),'es-primary');case 15:return btn('complete','Записать открытие '+icon('arrow'),'es-primary')+btn('restart','Пройти ещё раз','es-subtle');default:return '';}
  }
  function updateControls(){q('.es-actions').innerHTML=controls();}
  function accept(a,title,text){ready=true;mark(a);showTip(title,text,a,'success');updateControls();}
  function render(focus=false){const [id,scene,title,dialogue,instruction]=steps[s.step],hero=s.step===0||s.step===15;
   const name={factory:'Учебный участок',bench:'Верстак наладчика',control:'Рабочий терминал'}[scene];
   const mainArt=hero?`<img class="es-world-guide" src="assets/lab-guide-illustrated.png" alt="Наставник Очаково" draggable="false"><div class="es-intro"><span class="es-eyebrow">ОЧАКОВО / ${s.step===0?'ПЕРВАЯ СМЕНА':'СМЕНА ЗАВЕРШЕНА'}</span><h1 tabindex="-1">${s.step===0?'Другой формат.<br>Та же <em>точность.</em>':'Механика.<br>Автоматика.<br><em>Одна команда.</em>'}</h1><p>${s.step===0?'Попробуй работу<br>в инженерной команде.':'Ты переналадил учебный узел<br>и проверил результат.'}</p><div class="es-meta">${s.step===0?'8–10 минут <span>·</span> В твоём темпе':'Формат Б <span>·</span> Три успешных прохода'}</div><div class="es-actions">${controls()}</div><small>${s.step===0?'Опыт работы с оборудованием не требуется':'Твоё открытие: каждую настройку подтверждают проверкой'}</small></div>`:`<div class="es-scene-heading"><h1 tabindex="-1">${title}</h1></div>${scene==='factory'?machine(s):scene==='bench'?bench(s):terminal(s)}${s.step===2?'<aside class="es-order-note"><span class="es-eyebrow">ЗАДАНИЕ НА СМЕНУ</span><h2>Новый формат</h2><dl><div><dt>Тара</dt><dd>Широкая банка Б</dd></div><div><dt>Оснастка</dt><dd>Комплект Б</dd></div></dl></aside>':''}${s.step===8?'<aside class="es-gap-note"><span class="es-eyebrow">УЧЕБНАЯ КАРТОЧКА</span><strong>Рабочая отметка: 4</strong><span>Оставь место для прохода банки.</span></aside>':''}<div class="es-actions">${controls()}</div><div class="es-scene-caption"><b>${s.step<6?'01':s.step<9?'02':s.step<11?'03':'04'}</b>${s.step<6?'Знакомство с узлом':s.step<9?'Переналадка':s.step<11?'Автоматика':'Проверка результата'}</div>`;
   host.innerHTML=`<section class="es" data-step="${id}" data-scene="${scene}" aria-label="Инженерный участок"><header class="es-top"><a class="es-back" href="#map" aria-label="На карту завода">${icon('back')}</a><a class="es-brand" href="#map"><img src="assets/ochakovo-logo.png" alt="Очаково"></a><i class="es-divider"></i><div class="es-location"><b>Инженерный участок</b><span>${name}</span></div><nav aria-label="Управление игрой"><button data-es="journal" aria-label="Открыть журнал">${icon('book')}<span>Журнал</span><i>${s.step===15?4:s.step>=11?3:s.step>=9?2:s.step>=6?1:0}</i></button><button data-es="hint" aria-label="Подсказка">${icon('help')}<span>Подсказка</span></button><button data-es="pause" aria-pressed="false" aria-label="Пауза">${icon('pause')}</button></nav></header><section class="es-world">${mainArt}</section><footer class="es-coach">${hero?'':'<div class="es-mentor"><img src="assets/lab-guide-illustrated.png" alt="Наставник Очаково" draggable="false"></div>'}<div class="es-dialogue"><span class="es-speaker">ТВОЙ НАСТАВНИК</span><p>${dialogue}</p><span class="es-instruction">${instruction}</span></div>${s.step===0?'':btn('why','Зачем это в работе?','es-why')}</footer><div class="es-footer"><span>${storageOK?'Прогресс сохраняется на этом устройстве':'Сохранение недоступно — не закрывай вкладку'}</span><span>Учебная история · без таймера и штрафов</span></div><div class="es-live" role="status" aria-live="polite"></div><dialog class="es-dialog" aria-labelledby="es-dialog-title"></dialog></section>`;
   if(focus){q('h1').focus({preventScroll:true});tween(q('.es-world'),[{opacity:.65},{opacity:1}],220);}
   q('dialog').addEventListener('close',()=>{lastTrigger?.focus({preventScroll:true});});
  }
  function modal(kind){lastTrigger=document.activeElement;const journal=[['Задание','Новый формат Б требует другой оснастки.',s.step>=6],['Механика','Комплект Б установлен. Учебный зазор — 4.',s.step>=9],['Автоматика','Датчик → контроллер → привод. Задание Б.',s.step>=11],['Проверка','Пустой цикл пройден. Три банки без замечаний.',s.step===15]];
   const titles={journal:'Журнал смены',hint:'Следующий шаг',why:'Зачем это в работе?'};
   const content=kind==='journal'?journal.map(([t,d,done])=>`<div class="es-journal-row ${done?'done':''}"><b>${done?'✓':'○'} ${t}</b><p>${done?d:'Запись появится после выполнения этапа.'}</p></div>`).join(''):kind==='hint'?`<p>${steps[s.step][4]}</p><p>Нажимай на выделенные предметы. Текст рядом с ними объясняет, что происходит и почему.</p>`:'<p>В кейсе «Очаково» инженерное направление включает автоматизацию производственных линий и наладку оборудования.</p><p>Среди возможных задач практики — работа в паре с инженером, оцифровка линии и разработка улучшений. Здесь ты пробуешь общую логику: разобраться, настроить, проверить и передать результат.</p><small>Узел и параметры придуманы для обучения. Реальные работы проходят с наставником по инструкциям предприятия.</small>';
   q('dialog').innerHTML=`<button class="es-close" data-es="close" aria-label="Закрыть">×</button><span class="es-eyebrow">ИНЖЕНЕРНЫЙ УЧАСТОК</span><h2 id="es-dialog-title">${titles[kind]}</h2>${content}${btn('close','Вернуться к задаче','es-primary')}`;q('dialog').showModal();
  }
  async function run(a){if(busy)return;busy=true;tip=null;q('.es-object-popover')?.remove();q('.es-tip-line')?.remove();all('.es-actions button').forEach(b=>b.disabled=true);let end=[];
   if(a==='baseline')end=[tween(q('.es-moving-can'),[{transform:'translate(250px,211px)'},{transform:'translate(385px,202px)'}],1800)];
   if(a==='install')end=[tween(q('.es-assembly'),[{transform:'translateY(-95px)'},{transform:'translateY(0px)'}],1000)];
   if(a==='dry'){q('.es-belt').classList.add('es-running');end=[tween(q('.es-wheel'),[{rotate:'0deg'},{rotate:'360deg'}],2300)];}
   if(a==='test'){
    q('.es-belt').classList.add('es-running');q('.es-cans').innerHTML=[0,1,2].map(i=>can(220,211,true,String(i+1),`class="es-test-can"`)).join('');
    end=all('.es-test-can').map((el,i)=>{el.style.opacity='0';const a=tween(el,[{transform:'translate(220px,211px)',opacity:1},{transform:`translate(${840-i*100}px,210px)`,opacity:1}],(620-i*100)*4.2,i*1050);a.effect.updateTiming({easing:'linear'});return a;});
    let counted=0;
    const track=()=>{if(disposed)return;const count=end.filter((a,i)=>{const time=a.effect.getComputedTiming();return time.progress!==null&&time.progress>=(400/(620-i*100));}).length;if(count>counted){counted=count;q('.es-counter').textContent=`${count} / 3`;tween(q('.es-sensor-light'),[{fill:'#f3d17b'},{fill:'#84bc8e'},{fill:'#d6e8b3'}],350);}if(busy)signalFrame=requestAnimationFrame(track);};signalFrame=requestAnimationFrame(track);
   }
   try{await Promise.all(end.map(x=>x.finished));if(disposed)return;busy=false;ready=true;if(a==='test')q('.es-counter').textContent='3 / 3';q('.es-belt')?.classList.remove('es-running');updateControls();
    const notes={baseline:['Проход слишком узкий','Банка упёрлась в направляющие. Теперь найди причину.','.es-moving-can','retry'],install:['Комплект установлен','Направляющие на месте. Наставник проверил крепление.','.es-assembly','success'],dry:['Пустой цикл пройден','Привод и лента отработали без остановки. Можно проверить тару.','.es-motor','success'],test:['Три банки прошли','Датчик отметил каждую. Осталось осмотреть тару на выходе.','.es-cans','success']};showTip(...notes[a]);q('.es-actions button').focus({preventScroll:true});
   }catch{}
  }
  function act(a){lastAction=a;
   if(a==='close'){q('dialog').close();return;}
   if(a==='pause'){paused=!paused;animations.forEach(x=>{if(x.playState==='running'||x.playState==='paused')paused?x.pause():x.play();});q('.es').classList.toggle('es-paused',paused);q('[data-es=pause]').innerHTML=icon(paused?'play':'pause');q('[data-es=pause]').setAttribute('aria-label',paused?'Продолжить':'Пауза');q('[data-es=pause]').setAttribute('aria-pressed',String(paused));return;}
   if(paused)return;if(['why','hint','journal'].includes(a)){modal(a);return;}if(busy)return;
   const st=s.step;
   if(a==='restart'&&st===15){cleanupMotion();s=fresh();ready=false;tip=null;save();render(true);return;}
   if(a==='complete'&&st===15){onComplete();return;}
   if(a==='next'&&(ready||st===0||(st===1&&s.checked.length===3)||(st===9&&s.chain.length===3)||(st===13&&s.checked.length===3))){advance();return;}
   if(st===1&&['guides','sensor','motor'].includes(a)){if(!s.checked.includes(a))s.checked.push(a);save();mark(a);updateControls();const notes={guides:['Направляющие','Удерживают тару на траектории. Их расстояние подбирают под ширину банки.'],sensor:['Датчик','Замечает появление банки и передаёт сигнал контроллеру.'],motor:['Привод','Получает команду управления и двигает ленту конвейера.']};showTip(...notes[a],a);return;}
   if(st===2&&a.startsWith('format')){if(a==='formatB')accept(a,'Это новый формат','Широкая банка Б. Для неё понадобятся подходящие направляющие.');else showTip('Прежняя тара','Эта узкая банка относится к формату А. Сверь выбор с заданием.',a,'retry');return;}
   if((st===3&&a==='baseline')||(st===7&&a==='install')||(st===11&&a==='dry')||(st===12&&a==='test')){run(a);return;}
   if(st===4&&['guides','sensor','motor'].includes(a)){if(a==='guides')accept(a,'Причина найдена','Старый проход слишком узок для банки Б. Нужен другой комплект оснастки.');else showTip(a==='sensor'?'Датчик исправен':'Привод работает',a==='sensor'?'Сигнал от банки поступает. Проверь ширину прохода.':'Лента движется. Посмотри, во что упирается банка.',a,'retry');return;}
   if(st===5&&a==='prepare'){advance();return;}
   if(st===6&&a.startsWith('kit')){if(a==='kitB')accept(a,'Комплект Б подходит','Его проход рассчитан на широкую банку. Перенеси оснастку на макет.');else showTip('Слишком узко','Комплект А подходит прежней таре. Сравни проход с широкой банкой.',a,'retry');return;}
   if(st===8&&a==='gap'){if(s.gap===4)accept('.es-assembly','Настройка совпадает','Зазор выставлен на отметку 4 по учебной карточке.');else showTip(s.gap<4?'Проход слишком узкий':'Слишком большой зазор','Выставь отметку 4 по карточке: тара должна пройти и сохранить направление.','.es-assembly','retry');return;}
   if(st===9){if(a==='chainReset'){s.chain=[];save();tip=null;render();return;}if(['sensor','controller','drive'].includes(a)){if(a===['sensor','controller','drive'][s.chain.length]){s.chain.push(a);save();const names={sensor:'Датчик',controller:'Контроллер',drive:'Привод'};const cell=all('.es-signal-path span')[s.chain.length-1];cell.textContent=names[a];cell.classList.add('is-filled');mark(a);q(`[data-es="${a}"]`).disabled=true;updateControls();showTip(names[a],{sensor:'Первым появляется сигнал: банка обнаружена.',controller:'Контроллер обрабатывает сигнал и определяет команду.',drive:'Привод выполняет команду. Цепочка собрана.'}[a],a,'success');}else showTip('Сначала — обнаружение','После датчика нужен контроллер, после контроллера — привод.',a,'retry');return;}}
   if(st===10&&a.startsWith('recipe')){if(a==='recipeB')accept(a,'Задание Б применено','Механическая оснастка и программа теперь соответствуют одному формату.');else showTip('Форматы не совпадают','Установлен комплект Б. Выбери для него задание Б.',a,'retry');return;}
   if(st===13&&/^can[012]$/.test(a)){if(!s.checked.includes(a))s.checked.push(a);save();mark(a);updateControls();showTip(`Банка ${Number(a.slice(-1))+1} — без замечаний`,'Стоит ровно, повреждений нет. Проход без застревания.',a,'success');return;}
   if(st===14&&a.startsWith('record')){if(a==='recordGood')accept(a,'Запись готова','Указаны формат, настройка и результат проверки. Команда сможет продолжить работу.');else showTip('Не хватает деталей','Запиши, что изменили и чем подтвердили результат.',a,'retry');}
  }
  function click(e){const b=e.target.closest('[data-es]');if(b&&!b.disabled&&host.contains(b))act(b.dataset.es);}
  function keydown(e){if(e.target.matches('g[data-es]')&&['Enter',' '].includes(e.key)){e.preventDefault();act(e.target.dataset.es);}if(e.key==='Escape'&&!q('dialog').open){q('.es-object-popover')?.remove();q('.es-tip-line')?.remove();tip=null;}}
  function input(e){if(e.target.matches('.es-slider input')&&!paused){s.gap=Number(e.target.value);save();q('output').textContent=s.gap;q('.es-front-guide').setAttribute('d',`M295 ${310+s.gap*12}h410v15H295Z`);q('.es-object-popover')?.remove();q('.es-tip-line')?.remove();tip=null;}}
  host.addEventListener('click',click);host.addEventListener('keydown',keydown);host.addEventListener('input',input);window.addEventListener('resize',positionTip);render();
  return {destroy(){disposed=true;cleanupMotion();host.removeEventListener('click',click);host.removeEventListener('keydown',keydown);host.removeEventListener('input',input);window.removeEventListener('resize',positionTip);},getState:()=>structuredClone(s)};
 }
 window.EngineeringStory={mount,steps:steps.map(x=>x[0])};
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('engineering-story.css?v=3',document.currentScript.src).href;document.head.append(css);
 const learned='Подобрал оснастку под новый формат тары, связал датчик, контроллер и привод, проверил учебный узел и записал результат переналадки.';
 Object.assign(window.OchakovoShift.roles.engineering,{role:'Наладка и автоматизация',lead:'Другой формат. Та же точность — первая инженерная задача вместе с наставником.',learned,day:'Инженерное направление в кейсе объединяет наладку оборудования и автоматизацию производственных линий. Важно понимать механическую часть, управление и способ проверки результата.',tools:'Оснастка, задание на переналадку, схема автоматики, терминал и журнал.',skills:'Наблюдательность, техническое мышление, точность и работа с наставником.'});
 Object.assign(window.GameMissions.list.find(x=>x.id==='engineering'),{minutes:9,role:'Наладка и автоматизация'});
 window.OchakovoShift.register('engineering',a=>{let game,finished=false;a.root.classList.add('engineering-story-shell');return {start(){game=mount(a.content,{onComplete(){finished=true;const b=document.createElement('button');b.hidden=true;b.dataset.do='finish';a.root.append(b);b.click();b.remove();}});},act(){},done:()=>finished,result:()=>({learned}),cleanup(){game?.destroy();},managesFocus:true};});
})();
